{"rob": "robolang 1.3;

task relay(robot amr, robot arm, object part, location pickup, location handoff, location drop) {
    goal { object_at part drop; }
    plan {
        move amr to pickup;
        grasp amr part;
        move amr to handoff;
        place amr part at handoff;
        move arm to handoff;
        grasp arm part;
        move arm to drop;
        place arm part at drop;
    }
}
", "task": "relay", "bindings": [{"param": "amr", "id": "amr1"}, {"param": "arm", "id": "arm_b"}, {"param": "part", "id": "p2"}, {"param": "pickup", "id": "conveyor_in"}, {"param": "handoff", "id": "station2"}, {"param": "drop", "id": "bin"}]}
